# Let me verify the girth of the McGee graph
from collections import deque

def bfs_girth(edges, n):
    """Find girth of graph using BFS from each vertex"""
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    min_cycle = float('inf')

    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])

        while queue:
            u = queue.popleft()
            for w in adj[u]:
                if w not in dist:
                    dist[w] = dist[u] + 1
                    parent[w] = u
                    queue.append(w)
                elif parent[u] != w:
                    # Found a cycle
                    cycle_len = dist[u] + dist[w] + 1
                    min_cycle = min(min_cycle, cycle_len)

    return min_cycle

